package main

import (
	"database/sql"
	"encoding/json"
	"log"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strconv"
	"strings"

	"linkshelf/internal/store"

	_ "github.com/mattn/go-sqlite3"
)

func main() {
	// Open (or create) the SQLite database file.
	db, err := sql.Open("sqlite3", "linkshelf.db")
	if err != nil {
		log.Fatalf("failed to open database: %v", err)
	}
	// Ensure the DB is closed on exit.
	defer db.Close()

	// Initialise the schema if needed.
	if err := store.InitSchema(db); err != nil {
		log.Fatalf("failed to initialise schema: %v", err)
	}
	// Wire the store package to use this DB instance.
	store.DB = db

	// Register HTTP handlers.
	http.HandleFunc("/", handleRoot)
	http.HandleFunc("/static/", handleStatic)
	http.HandleFunc("/api/links", handleListCreate) // GET list, POST create
	http.HandleFunc("/api/links/", handleDelete)    // DELETE specific link

	// Start the server.
	log.Println("server listening on :8080")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatalf("server failed: %v", err)
	}
}

// handleRoot serves the main HTML page.
func handleRoot(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/" {
		http.NotFound(w, r)
		return
	}
	http.ServeFile(w, r, filepath.Join("web", "index.html"))
}

// handleStatic serves static assets under /static/.
func handleStatic(w http.ResponseWriter, r *http.Request) {
	// Reject any path traversal attempts.
	if strings.Contains(r.URL.Path, "..") {
		http.NotFound(w, r)
		return
	}
	relPath := strings.TrimPrefix(r.URL.Path, "/static/")
	if relPath == "" {
		http.NotFound(w, r)
		return
	}
	// Prevent escaped sequences from being interpreted as paths.
	if u, err := url.PathUnescape(relPath); err == nil && strings.Contains(u, "..") {
		http.NotFound(w, r)
		return
	}
	absPath := filepath.Join("web", relPath)
	if _, err := os.Stat(absPath); err != nil {
		http.NotFound(w, r)
		return
	}
	http.ServeFile(w, r, absPath)
}

// handleListCreate dispatches GET (list) and POST (create) on /api/links.
func handleListCreate(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		handleList(w, r)
	case http.MethodPost:
		handleCreate(w, r)
	default:
		http.Error(w, `{"error":"method not allowed"}`, http.StatusMethodNotAllowed)
	}
}

// handleList returns all stored links as JSON.
func handleList(w http.ResponseWriter, r *http.Request) {
	links, err := store.List()
	if err != nil {
		http.Error(w, `{"error":"internal error"}`, http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(links)
}

// handleCreate reads a JSON payload to create a new link.
func handleCreate(w http.ResponseWriter, r *http.Request) {
	var payload struct {
		Title string `json:"title"`
		URL   string `json:"url"`
	}
	if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
		http.Error(w, `{"error":"invalid json"}`, http.StatusBadRequest)
		return
	}
	link := store.Link{
		Title: payload.Title,
		URL:   payload.URL,
	}
	id, err := store.Create(link)
	if err != nil {
		resp := map[string]string{"error": err.Error()}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusBadRequest)
		json.NewEncoder(w).Encode(resp)
		return
	}
	link.ID = id
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(link)
}

// handleDelete removes a link by ID.
func handleDelete(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodDelete {
		http.Error(w, `{"error":"method not allowed"}`, http.StatusMethodNotAllowed)
		return
	}
	// Expected format: /api/links/{id}
	idStr := strings.TrimPrefix(r.URL.Path, "/api/links/")
	id64, err := strconv.ParseInt(idStr, 10, 64)
	if err != nil {
		http.Error(w, `{"error":"invalid id"}`, http.StatusBadRequest)
		return
	}
	if err := store.Delete(id64); err != nil {
		resp := map[string]string{"error": err.Error()}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusNotFound)
		json.NewEncoder(w).Encode(resp)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

