package main

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"testing"

	"linkshelf/internal/store"

	_ "github.com/mattn/go-sqlite3"
)

func initTestDB(t *testing.T) {
	t.Helper()
	db, err := sql.Open("sqlite3", ":memory:")
	if err != nil {
		t.Fatalf("failed to open in-memory DB: %v", err)
	}
	if err := store.InitSchema(db); err != nil {
		t.Fatalf("failed to init schema: %v", err)
	}
	store.DB = db
	t.Cleanup(func() {
		db.Close()
	})
}

// TestMainTest contains integration-style tests for the server handlers.
// These tests require a valid web/index.html file for the root handler test.

func TestHandleRoot(t *testing.T) {
	// Ensure web/index.html exists for root handler to serve.
	setupWebHTML(t)
	defer os.RemoveAll("web")

	req := httptest.NewRequest(http.MethodGet, "/", nil)
	w := httptest.NewRecorder()
	handleRoot(w, req)

	if w.Code != http.StatusOK {
		t.Fatalf("expected 200, got %d", w.Code)
	}
	ct := w.Header().Get("Content-Type")
	if ct == "" || ct == "application/json" {
		t.Fatalf("expected non-JSON content type, got %q", ct)
	}
}

func TestHandleListEmpty(t *testing.T) {
	initTestDB(t)
	req := httptest.NewRequest(http.MethodGet, "/api/links", nil)
	w := httptest.NewRecorder()
	handleList(w, req)

	if w.Code != http.StatusOK {
		t.Fatalf("expected 200, got %d", w.Code)
	}
	var links []store.Link
	if err := json.NewDecoder(w.Body).Decode(&links); err != nil {
		t.Fatalf("failed to decode JSON response: %v", err)
	}
	if len(links) != 0 {
		t.Fatalf("expected empty list, got %d items", len(links))
	}
}

func TestHandleCreateAndList(t *testing.T) {
	initTestDB(t)
	payload := map[string]string{"title": "Example", "url": "https://example.com"}
	body, _ := json.Marshal(payload)
	req := httptest.NewRequest(http.MethodPost, "/api/links", nil)
	req.Body = jsonBody(body)
	w := httptest.NewRecorder()
	handleCreate(w, req)

	if w.Code != http.StatusCreated {
		t.Fatalf("expected 201, got %d: %s", w.Code, w.Body.String())
	}

	var created store.Link
	if err := json.NewDecoder(w.Body).Decode(&created); err != nil {
		t.Fatalf("failed to decode created link: %v", err)
	}
	if created.ID == 0 {
		t.Fatal("expected non-zero ID")
	}
	if created.Title != "Example" {
		t.Fatalf("expected title 'Example', got %q", created.Title)
	}

	// Verify listing includes the new link.
	listReq := httptest.NewRequest(http.MethodGet, "/api/links", nil)
	listW := httptest.NewRecorder()
	handleList(listW, listReq)

	var links []store.Link
	if err := json.NewDecoder(listW.Body).Decode(&links); err != nil {
		t.Fatalf("failed to decode list response: %v", err)
	}
	if len(links) != 1 {
		t.Fatalf("expected 1 link, got %d", len(links))
	}
	if links[0].ID != created.ID {
		t.Fatalf("expected ID %d, got %d", created.ID, links[0].ID)
	}
}

func TestHandleDelete(t *testing.T) {
	initTestDB(t)
	// First create a link.
	payload := map[string]string{"title": "To Delete", "url": "https://delete.me"}
	body, _ := json.Marshal(payload)
	createReq := httptest.NewRequest(http.MethodPost, "/api/links", nil)
	createReq.Body = jsonBody(body)
	createW := httptest.NewRecorder()
	handleCreate(createW, createReq)

	var created store.Link
	if err := json.NewDecoder(createW.Body).Decode(&created); err != nil {
		t.Fatalf("failed to decode created link: %v", err)
	}

	// Delete it.
	delReq := httptest.NewRequest(http.MethodDelete, "/api/links/"+jsonNumber(created.ID), nil)
	delW := httptest.NewRecorder()
	handleDelete(delW, delReq)

	if delW.Code != http.StatusNoContent {
		t.Fatalf("expected 204, got %d: %s", delW.Code, delW.Body.String())
	}

	// Listing should be empty again.
	listReq := httptest.NewRequest(http.MethodGet, "/api/links", nil)
	listW := httptest.NewRecorder()
	handleList(listW, listReq)

	var links []store.Link
	if err := json.NewDecoder(listW.Body).Decode(&links); err != nil {
		t.Fatalf("failed to decode list response: %v", err)
	}
	if len(links) != 0 {
		t.Fatalf("expected empty list after delete, got %d items", len(links))
	}
}

// TestHandleDeleteInvalidID tests that an invalid ID returns 400.
func TestHandleDeleteInvalidID(t *testing.T) {
	req := httptest.NewRequest(http.MethodDelete, "/api/links/xyz", nil)
	w := httptest.NewRecorder()
	handleDelete(w, req)

	if w.Code != http.StatusBadRequest {
		t.Fatalf("expected 400, got %d", w.Code)
	}
}

// TestHandleDeleteMethodNotAllowed tests non-DELETE method on /api/links/{id}.
func TestHandleDeleteMethodNotAllowed(t *testing.T) {
	req := httptest.NewRequest(http.MethodGet, "/api/links/1", nil)
	w := httptest.NewRecorder()
	handleDelete(w, req)

	if w.Code != http.StatusMethodNotAllowed {
		t.Fatalf("expected 405, got %d", w.Code)
	}
}

// TestHandleListCreateMethodNotAllowed tests that a non-GET, non-POST method returns 405.
func TestHandleListCreateMethodNotAllowed(t *testing.T) {
	req := httptest.NewRequest(http.MethodPut, "/api/links", nil)
	w := httptest.NewRecorder()
	handleListCreate(w, req)

	if w.Code != http.StatusMethodNotAllowed {
		t.Fatalf("expected 405, got %d", w.Code)
	}
}

// Helper: create web/index.html for tests.
func setupWebHTML(t *testing.T) {
	t.Helper()
	dir := filepath.Join("web")
	if err := os.MkdirAll(dir, 0755); err != nil {
		t.Fatalf("failed to create web dir: %v", err)
	}
	if err := os.WriteFile(filepath.Join(dir, "index.html"), []byte("<html></html>"), 0644); err != nil {
		t.Fatalf("failed to write index.html: %v", err)
	}
}

// Helper: return an io.ReadCloser from a byte slice.
func jsonBody(b []byte) *jsonBodyReader {
	return &jsonBodyReader{Data: b}
}

type jsonBodyReader struct {
	Data []byte
	pos  int
}

func (r *jsonBodyReader) Read(p []byte) (int, error) {
	if r.pos >= len(r.Data) {
		return 0, nil
	}
	n := copy(p, r.Data[r.pos:])
	r.pos += n
	return n, nil
}

func (r *jsonBodyReader) Close() error { return nil }

// Helper: convert int64 to JSON number string (just the digits).
func jsonNumber(n int64) string {
	b, _ := json.Marshal(n)
	return string(b)
}

